    ss[(f + F_KPOS) as usize] = ent2 + KH;
    ss[(f + F_KLEN) as usize] = klen;
    ss[(f + F_VN) as usize] = ss[(f + F_VN) as usize] + 1;
    if vo2 != 0 {
        ss[(f + F_VMARK) as usize] = 1;
    }
