    ss[(f + F_KID) as usize] = kid;
    ss[(f + F_MCNQ) as usize] = cnq;
    ss[(f + F_NC) as usize] = nc;
    ss[(f + F_VNQ) as usize] = vnq;
    ss[(f + F_PS2) as usize] = ps2;
    ss[(f + F_PH) as usize] = M_LVAL;
